CREATE TABLE `seo_page_overrides` (`path` text PRIMARY KEY NOT NULL, `seo_title` text NOT NULL DEFAULT '', `meta_description` text NOT NULL DEFAULT '', `og_title` text NOT NULL DEFAULT '', `og_description` text NOT NULL DEFAULT '', `og_image` text NOT NULL DEFAULT '', `canonical_url` text NOT NULL DEFAULT '', `updated_at` integer NOT NULL DEFAULT (unixepoch()), `updated_by` text NOT NULL DEFAULT '');
